INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31111, 'Acts 19:17', 'Acts', 19, 17, 'کله چې د افسیس ټول اوسېدونکي یهودیان او یونانیان د دې پېښې څخه خبر شول، نو په هغوی ټولو باندې وېره راغله او د څښتن عیسی نوم نور هم سرلوړی شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_17.mp3', '', 1761754199, 1761754199),
(31112, 'Acts 19:18', 'Acts', 19, 18, 'ډېرو خلکو چې ایمان یې راوړی ؤ، راغلل او دا اقرار یې وکړ چې هغوی جادوګري کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_18.mp3', '', 1761754199, 1761754199),
(31113, 'Acts 19:19', 'Acts', 19, 19, 'ډېرو جادوګرانو خپل د جادوګرۍ کتابونه راټول کړل او د خلکو په مخکې یې وسوځول. کله چې هغوی د کتابونو قیمتونه حساب کړل، نو د هغو بیه پنځوس زره د سپینو زرو سکې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_19.mp3', '', 1761754199, 1761754199),
(31114, 'Acts 19:20', 'Acts', 19, 20, 'په دې ډول د څښتن عیسی پیغام خپرېده او په خلکو یې ډېره اغېزه کوله. په افسیس کې شور او غوغا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_20.mp3', '', 1761754199, 1761754199),
(31115, 'Acts 19:21', 'Acts', 19, 21, 'د دې ټولو پېښو نه وروسته پولوس د روح القدس په لارښوونه پرېکړه وکړه چې مقدونیې او جنوبي یونان ته سفر وکړي او وروسته بیا اورشلیم ته لاړ شي. هغه وویل: «هغه ځای ته د تللو نه وروسته باید د روم ښار هم ووینم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_21.mp3', '', 1761754199, 1761754199),
(31116, 'Acts 19:22', 'Acts', 19, 22, 'هغه خپل دوه ملګري یعنې تیموتاوس او اراستوس مقدونیې ته ولېږل او په خپله د یو څه وخت دپاره د اسیا په ولایت کې پاتې شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_22.mp3', '', 1761754199, 1761754199),
(31117, 'Acts 19:23', 'Acts', 19, 23, 'په دې وخت کې د څښتن عیسی د لارې له امله سخت شور او غوغا پیدا شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_23.mp3', '', 1761754199, 1761754199),
(31118, 'Acts 19:24', 'Acts', 19, 24, 'هلته د دیمیتریوس په نوم یو زرګر ؤ چې د ارتیمیسې د بت د عبادت ځای د سپینو زرو نمونې به یې جوړولې او په دې ډول یې د کسبګرو دپاره یو ښه او ګټور کاروبار برابر کړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_24.mp3', '', 1761754199, 1761754199),
(31119, 'Acts 19:25', 'Acts', 19, 25, 'نو دیمیتریوس هغوی او د هغوی په شان نور کسبګر سره راټول کړل او ورته یې وویل: «ای ملګرو، تاسو پوهېږئ چې مونږ له همدې کاروبار څخه ښه ګټه تر‌لاسه کوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_25.mp3', '', 1761754199, 1761754199),
(31120, 'Acts 19:26', 'Acts', 19, 26, 'لکه څنګه چې تاسو وینئ او اورئ چې دې پولوس یوازې په افسیس کې نه، بلکې د اسیا په ټول ولایت کې ګڼ شمېر خلک په خپلو خبرو ځان ته را‌اړولي او بې‌لارې کړي دي. هغه وایي چې د انسان په لاس جوړ شوي خدایان بالکل خدایان نه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_26.mp3', '', 1761754199, 1761754199),
(31121, 'Acts 19:27', 'Acts', 19, 27, 'نو دا خطر شته چې نه یوازې دا چې زمونږ کاروبار به بدنام شي بلکې د دې خطر هم شته چې زمونږ د لوی خدای ارتیمیسې د عبادت ځای به هم بې‌اعتباره شي او د هغې شان او شوکت چې په اسیا او ټوله نړۍ کې ورته عبادت کیږي، هم له منځه لاړ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_27.mp3', '', 1761754199, 1761754199),
(31122, 'Acts 19:28', 'Acts', 19, 28, 'کله چې هغوی دا خبرې واورېدلې، نو ډېر په قهر شول او چیغې یې ووهلې: «لویه ده د افسیسیانو ارتیمیسه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_28.mp3', '', 1761754199, 1761754199),
(31123, 'Acts 19:29', 'Acts', 19, 29, 'په ټول ښار کې شور او غوغا پیدا شوه. خلکو ګایوس او ارسترخوس چې د مقدونیې څخه وو او د پولوس د سفر ملګري وو، ونیول او په راښکلو راښکلو یې د ښار د غونډې ځای ته یووړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_29.mp3', '', 1761754199, 1761754199),
(31124, 'Acts 19:30', 'Acts', 19, 30, 'پولوس غوښتل چې دننه ورشي او د خلکو سره خبرې وکړي، خو ایماندارانو هغه پرېنښود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_30.mp3', '', 1761754199, 1761754199),
(31125, 'Acts 19:31', 'Acts', 19, 31, 'د ولایت ځینو واکمنانو چې د پولوس ملګري وو هم هغه ته پیغام ورولېږه او هغه ته یې زاري وکړه چې د غونډې ځای ته لاړ نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_31.mp3', '', 1761754199, 1761754199),
(31126, 'Acts 19:32', 'Acts', 19, 32, 'په دې وخت کې غونډه ګډه وډه شوه او ځینو به په چیغو چیغو کې یو څه او ځینو به بل څه ویل، ځکه چې په هغوی کې ډېر خلک په دې هم نه پوهېدل چې د څه دپاره دلته راټول شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_32.mp3', '', 1761754199, 1761754199),
(31127, 'Acts 19:33', 'Acts', 19, 33, 'ځینو یهودي مشرانو د سکندر په نوم سړی د خلکو د ګڼې ګوڼې مخې ته ورټېله کړ او هغه ته یې وویل چې یو‌څه باید ووایي. هغه په خپل لاس اشاره وکړه چې خلک غلي شي او کوښښ یې وکړ چې هر هغه څه چې شوي وو، هغه بیان کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_33.mp3', '', 1761754199, 1761754199),
(31128, 'Acts 19:34', 'Acts', 19, 34, 'خو کله چې خلک پوه شول چې سکندر یهودي دی، نو ټولو په یو اواز دوه ساعته چیغې ووهلې: «لویه ده د افسیسیانو خدای ارتیمیسه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_34.mp3', '', 1761754199, 1761754199),
(31129, 'Acts 19:35', 'Acts', 19, 35, 'په پای کې ښاروال خلک غلي کړل او ویې ویل: «ای د افسیس خلکو، ټولو ته معلومه ده چې د افسیس ښار د لویې ارتیمیسې د عبادتځای او د هغې سپېڅلې تیږې ساتونکی دی چې د اسمان څخه راغورځېدلې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_35.mp3', '', 1761754199, 1761754199),
(31130, 'Acts 19:36', 'Acts', 19, 36, 'نو څرنګه چې هېڅوک د دې حقیقتونو څخه انکار نه شي کولای، تاسو باید غلي شئ او بې‌سنجشه کار ونه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_36.mp3', '', 1761754199, 1761754199),
(31131, 'Acts 19:37', 'Acts', 19, 37, 'دا خلک چې تاسو دلته راوستلي دي هغوی نه د عبادتځای څخه غلا کړې ده او نه یې زمونږ خدای ارتیمیسې ته کفر ویلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_37.mp3', '', 1761754199, 1761754199),
(31132, 'Acts 19:38', 'Acts', 19, 38, 'که چېرې دیمیتریوس او د هغه نور کسبګران د هغوی په خلاف دعوه چلول غواړي، نو د محکمو دروازې خلاصې دي او قاضیان هم شته، نو هغوی کولای شي چې په یو بل باندې دعوه وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_38.mp3', '', 1761754199, 1761754199),
(31133, 'Acts 19:39', 'Acts', 19, 39, 'که تاسو نور څه غواړئ، نو د هغې په هکله دې په یوه رسمي غونډه کې پرېکړه وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_39.mp3', '', 1761754199, 1761754199),
(31134, 'Acts 19:40', 'Acts', 19, 40, 'ځکه چې دا خطر شته چې مونږ د نن ورځې د شور او غوغا په خاطر تورن شو او د دې ګډوډۍ دپاره کومه بهانه نشته او مونږ به ونه شو کولای چې د دې دپاره کوم سم دلیل وړاندې کړو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_40.mp3', '', 1761754199, 1761754199),
(31135, 'Acts 19:41', 'Acts', 19, 41, 'کله چې هغه دا خبره وکړه، نو د غونډې خلک یې رخصت کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts19_verse_41.mp3', '', 1761754199, 1761754199),
(31136, 'Romans 2:1', 'Romans', 2, 1, 'نو له دې امله ای انسانه، ته څوک یې چې د نورو په هکله قضاوت کوې؟ ته چې هرڅوک یې، تا سره هېڅ عذر نشته، ځکه کله چې ته د نورو په هکله قضاوت کوې او بیا په خپله هماغه کار کوې چې هغوی یې کوي، نو په خپله خپل ځان ملامتوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_1.mp3', '', 1761754199, 1761754199),
(31137, 'Romans 2:2', 'Romans', 2, 2, 'مونږ پوهېږو کله چې خدای د هغو خلکو په هکله چې داسې کارونه کوي، قضاوت کوي، نو هغه په حقه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_2.mp3', '', 1761754199, 1761754199),
(31138, 'Romans 2:3', 'Romans', 2, 3, 'خو ای انسانه، ته چې د نورو په هکله قضاوت کوې او په خپله هماغه کارونه کوې، ایا ګومان کوې چې د خدای د قضاوت نه به وتښتې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_3.mp3', '', 1761754199, 1761754199),
(31139, 'Romans 2:4', 'Romans', 2, 4, 'یا دا چې د خدای ډېرې زیاتې مهربانۍ، زغم او صبر ته په سپکه سترګه ګورې؟ ایا په دې نه پوهېږې چې د خدای د مهربانۍ مقصد دا دی چې هغه تاته وښایي چې ته توبه وباسې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_4.mp3', '', 1761754199, 1761754199),
(31140, 'Romans 2:5', 'Romans', 2, 5, 'خو دا چې ته سرزوری یې او د خپلو ګناهونو نه لاس نه اخلې، نو ته خپله سزا په هغه ورځ چې کله د خدای غضب او عادلانه قضاوت ښکاره شي، نوره هم زیاتوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_5.mp3', '', 1761754199, 1761754199),
(31141, 'Romans 2:6', 'Romans', 2, 6, 'خدای به هرچا ته د هغه د عملونو له مخې چې کړي یې دي، بدل ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_6.mp3', '', 1761754199, 1761754199),
(31142, 'Romans 2:7', 'Romans', 2, 7, 'کوم خلک چې په صبر او زغم سره ښه کارونه کوي او د جلال، عزت او نه‌فناکېدونکي ژوند په لټه کې دي، نو هغوی ته به خدای تلپاتې ژوندون ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_7.mp3', '', 1761754199, 1761754199),
(31143, 'Romans 2:8', 'Romans', 2, 8, 'خو کوم خلک چې ځان خوښوونکي دي، حقیقت نه مني او بدو کارونو پسې ګرځي، نو په هغوی باندې به خدای خپل قهر او غضب نازل کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_8.mp3', '', 1761754199, 1761754199),
(31144, 'Romans 2:9', 'Romans', 2, 9, 'د هغو خلکو دپاره به چې بد کارونه کوي، مصیبت او کړاوونه وي، لومړی د یهودیانو دپاره او بیا د غیریهودیانو دپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_9.mp3', '', 1761754199, 1761754199),
(31145, 'Romans 2:10', 'Romans', 2, 10, 'خو خدای به هغو ټولو خلکو ته چې ښه کارونه کوي، جلال، عزت او سوله ورکړي، لومړی یهودیانو ته او بیا غیریهودیانو ته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_10.mp3', '', 1761754199, 1761754199),
(31146, 'Romans 2:11', 'Romans', 2, 11, 'ځکه چې خدای د هېچا طرفداري نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_11.mp3', '', 1761754199, 1761754199),
(31147, 'Romans 2:12', 'Romans', 2, 12, 'هغه ټول خلک چې د موسی شریعت نه لري او ګناه کوي، نو هغوی به بې له شریعته له منځه ځي او د یهودیانو سره چې شریعت شته او ګناه کوي، نو د هغوی سره به د شریعت له مخې قضاوت کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_12.mp3', '', 1761754199, 1761754199),
(31148, 'Romans 2:13', 'Romans', 2, 13, 'ځکه چې یوازې د شریعت په اورېدلو سره هېڅوک د خدای په نظر کې عادل نه ګڼل کیږي، بلکې د شریعت په حکمونو باندې په عمل کولو سره عادل ګڼل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_13.mp3', '', 1761754199, 1761754199),
(31149, 'Romans 2:14', 'Romans', 2, 14, 'کله چې غیریهودیان چې شریعت نه لري په طبیعي توګه د شریعت په حکمونو باندې عمل کوي، نو د هغوی شریعت په خپله هغوی دي، که څه هم هغوی د موسی شریعت نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_14.mp3', '', 1761754199, 1761754199),
(31150, 'Romans 2:15', 'Romans', 2, 15, 'د هغوی عملونه دا ښکاره کوي چې د شریعت حکمونه د هغوی په زړونو کې لیکل شوي دي. د هغوی وجدان د دې شاهدي ورکوي، ځکه چې د هغوی خیالونه یا هغوی ملامتوي او یا د هغوی څخه دفاع کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_15.mp3', '', 1761754199, 1761754199),
(31151, 'Romans 2:16', 'Romans', 2, 16, 'نو د هغه زېري له مخې چې زه یې ورکوم، دا کار به په هغه ورځ وشي کله چې خدای د عیسی مسیح په وسیله د ټولو انسانانو د پټو خیالونو په هکله قضاوت کوي. یهودیان او شریعت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_16.mp3', '', 1761754199, 1761754199),
(31152, 'Romans 2:17', 'Romans', 2, 17, 'خو ته خپل ځان ته یهودي وایې او په شریعت باندې ولاړ یې او د خدای سره په اړیکو لرلو باندې ویاړ کوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_17.mp3', '', 1761754199, 1761754199),
(31153, 'Romans 2:18', 'Romans', 2, 18, 'ته د خدای په ارادې باندې پوهېږې او د شریعت څخه دې دا زده کړي دي چې هرڅه چې ښه دي غوره کړې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_18.mp3', '', 1761754199, 1761754199),
(31154, 'Romans 2:19', 'Romans', 2, 19, 'او په دې یقین لرې چې د ړندو دپاره لارښوونکی یې او د هغو خلکو دپاره رڼا یې کوم چې په تیاره کې دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_19.mp3', '', 1761754199, 1761754199),
(31155, 'Romans 2:20', 'Romans', 2, 20, 'د ناپوهه خلکو استاذ او د ماشومانو ښوونکی یې. ته د شریعت خاوند یې چې په هغه کې په پوره توګه پوهه او حقیقت شته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_20.mp3', '', 1761754199, 1761754199),
(31156, 'Romans 2:21', 'Romans', 2, 21, 'نو بیا ته چې نورو ته تعلیم ورکوې، ولې خپل ځان ته تعلیم نه ورکوې؟ ته نورو ته وعظ کوې چې غلا مه کوئ، ایا ته په خپله غلا نه کوې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_21.mp3', '', 1761754199, 1761754199),
