(31160, 'Romans 2:25', 'Romans', 2, 25, 'که چېرې ته په شریعت باندې عمل وکړې، نو سنت کېدل ارزښت لري، خو که ته د شریعت نه سرغړونه کوې، نو هغه به داسې وي لکه چې ته بالکل سنت شوی نه یې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_25.mp3', '', 1761754199, 1761754199),
(31161, 'Romans 2:26', 'Romans', 2, 26, 'نو که چېرې یو غیریهودي چې سنت شوی نه دی او د شریعت په حکمونو باندې عمل کوي، ایا خدای به هغه سنت شوی ونه ګڼي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_26.mp3', '', 1761754199, 1761754199),
(31162, 'Romans 2:27', 'Romans', 2, 27, 'او یو څوک چې په جسماني توګه سنت شوی نه دی خو د خدای په حکمونو باندې عمل کوي، نو هغه به تا خپله په هغه شریعت باندې چې درسره موجود دی او سنت شوی هم یې، خو په شریعت باندې عمل نه کوې، ملامته کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_27.mp3', '', 1761754199, 1761754199),
(31163, 'Romans 2:28', 'Romans', 2, 28, 'ځکه چې رښتینی یهودي هغه نه دی چې یوازې په ظاهره یهودي وي او که چېرې څوک سنت شوی وي، نو معنی یې دا نه ده چې هغه رښتینی یهودي دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_28.mp3', '', 1761754199, 1761754199),
(31164, 'Romans 2:29', 'Romans', 2, 29, 'بلکې رښتینی یهودي هغه دی چې په باطن کې یهودي وي، او رښتینی سنت کېدل د زړه سنت کېدل دي. دا د خدای د روح کار دی، نه د لیکل شوي شریعت کار. د داسې کس صفت د خدای له خوا کیږي، نه د انسان له خوا.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans2_verse_29.mp3', '', 1761754199, 1761754199),
(31165, 'Titus 3:1', 'Titus', 3, 1, 'ایماندارانو ته ور په یاد کړه چې د حاکمانو او د واک د خاوندانو تابعداري او د هغوی اطاعت دې کوي او د هر نېک کار دپاره دې تیار اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus3_verse_1.mp3', '', 1761754199, 1761754199),
(31166, 'Titus 3:2', 'Titus', 3, 2, 'هغوی ته ووایه چې د هېچا په هکله دې بد نه وایي او شخړه دې نه کوي، بلکې نرم مزاجه او د ټولو خلکو په وړاندې دې باادبه اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus3_verse_2.mp3', '', 1761754199, 1761754199),
(31167, 'Titus 3:3', 'Titus', 3, 3, 'ځکه چې مونږ هم یو وخت ناپوهه، نافرمانه، بې‌لارې او د هر ډول نفساني غوښتنو او عیاشیو غلامان وو او په کينې او بخیلتوب کې مو خپل ژوند کاوه. نورو زمونږ نه کرکه کوله او مونږ د نورو نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus3_verse_3.mp3', '', 1761754199, 1761754199),
(31168, 'Titus 3:4', 'Titus', 3, 4, 'خو کله چې زمونږ د خلاصوونکي خدای مهرباني او مینه ښکاره شوه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus3_verse_4.mp3', '', 1761754199, 1761754199),
