(31189, 'Matthew 3:10', 'Matthew', 3, 10, 'همدا‌اوس د ونو بېخونو ته تبر نیول شوی دی او هره ونه چې ښه مېوه نه نیسي هغه به ووهل شي او په اور کې به واچول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_10.mp3', '', 1761754199, 1761754199),
(31190, 'Matthew 3:11', 'Matthew', 3, 11, 'زه تاسو ته د توبې ویستلو په خاطر په اوبو باندې د تعمید غسل درکوم، خو زما څخه وروسته چې څوک راروان دی، هغه زما څخه ډېر زورور دی. زه د هغه د څپلیو د راپورته کولو لایق هم نه یم. هغه به تاسو ته په روح القدس او اور د تعمید غسل درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_11.mp3', '', 1761754199, 1761754199),
(31191, 'Matthew 3:12', 'Matthew', 3, 12, 'هغه خپله ښاخۍ په لاس کې نیولې ده او په هغې باندې به خپل درمند پاکوي. غنم به په ګودام کې ټولوي، خو بوس به په هغه اور کې سوځوي چې هېڅکله نه مړ کیږي.» عیسی د تعمید غسل اخلي (مرقوس ۱‏:‌۹‌‏-‌۱۱ او لوقا ۳‏:‌۲۱‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_12.mp3', '', 1761754199, 1761754199),
(31192, 'Matthew 3:13', 'Matthew', 3, 13, 'بیا عیسی د جلیل څخه د اردن سیند ته راغی، ترڅو د یحیی په لاس د تعمید غسل واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_13.mp3', '', 1761754199, 1761754199),
(31193, 'Matthew 3:14', 'Matthew', 3, 14, 'یحیی کوښښ وکړ چې هغه د دې کار نه منع کړي او ورته ویې ویل: «زه باید ستا په لاس د تعمید غسل واخلم، خو ته ماته راځې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_14.mp3', '', 1761754199, 1761754199),
(31194, 'Matthew 3:15', 'Matthew', 3, 15, 'خو عیسی په ځواب کې وویل: «پرېږده چې اوس همداسې وشي، ځکه چې دا زمونږ دپاره ښه ده چې د خدای رضا پوره کړو.» بیا یحیی ومنله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_15.mp3', '', 1761754199, 1761754199),
(31195, 'Matthew 3:16', 'Matthew', 3, 16, 'کله چې عیسی د تعمید غسل واخیست، نو سمدلاسه د اوبو څخه راووت. بیا د اسمان دروازه پرانیستل شوه او هغه د خدای روح ولیده چې د کوترې په شکل رانازل شو او په هغه باندې کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_16.mp3', '', 1761754199, 1761754199),
(31196, 'Matthew 3:17', 'Matthew', 3, 17, 'بیا د اسمان څخه یو اواز راغی او ویې ویل: «دا زما ګران زوی دی چې زه ترې خوشحاله یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew3_verse_17.mp3', '', 1761754199, 1761754199),
(31197, 'Hebrews 3:1', 'Hebrews', 3, 1, 'نو ای سپېڅلو خویندو او ورونو، تاسو چې د خدای له خوا په اسماني بلنه کې شریک یئ، د عیسی په هکله فکر وکړئ چې د هغه په اړه مونږ اقرار کوو چې زمونږ رسول او لوی کاهن دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_1.mp3', '', 1761754199, 1761754199),
(31198, 'Hebrews 3:2', 'Hebrews', 3, 2, 'عیسی خدای ته وفادار ؤ چې هغه یې ټاکلی ؤ، لکه څنګه چې موسی د خدای په ټول کور کې وفادار ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_2.mp3', '', 1761754199, 1761754199),
(31199, 'Hebrews 3:3', 'Hebrews', 3, 3, 'نو عیسی د موسی نه زیات د جلال لایق دی، لکه څنګه چې کور جوړوونکی د کور نه زیات عزت لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_3.mp3', '', 1761754199, 1761754199),
(31200, 'Hebrews 3:4', 'Hebrews', 3, 4, 'ځکه چې هر کور د یو چا په لاس جوړیږي او خدای د ټولو شیانو جوړوونکی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_4.mp3', '', 1761754199, 1761754199),
(31201, 'Hebrews 3:5', 'Hebrews', 3, 5, 'موسی د خدای په ټول کور کې د یو خدمتګار په توګه وفادار ؤ او د هغو شیانو په هکله به یې شاهدي ورکوله چې خدای به یې په راتلونکې کې ووایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_5.mp3', '', 1761754199, 1761754199),
(31202, 'Hebrews 3:6', 'Hebrews', 3, 6, 'خو عیسی د زوی او د کور د خاوند په توګه د خدای د کور وفادار دی. مونږ د هغه کور یو، په دې شرط چې که مونږ هغه پوره ډاډ او ویاړ چې مونږ ته هیله راکوي، ټینګ وساتو. د خدای د قوم دپاره ارامي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_6.mp3', '', 1761754199, 1761754199),
(31203, 'Hebrews 3:7', 'Hebrews', 3, 7, 'نو لکه څنګه چې روح القدس وایي: «که چېرې واورئ نن تاسو د خدای اواز', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_7.mp3', '', 1761754199, 1761754199),
(31204, 'Hebrews 3:8', 'Hebrews', 3, 8, 'نو مه سختوئ خپل زړونه لکه چې څنګه سرکښي وکړه د خدای په وړاندې ستاسو پلرونو او هغه یې وازمایلو دښته کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_8.mp3', '', 1761754199, 1761754199),
(31205, 'Hebrews 3:9', 'Hebrews', 3, 9, 'که څه هم هغه کارونه چې ما کړي وو څلوېښتو کالو کې، هلته ولیدل ستاسو پلرونو خو بیاهم هغوی زه وازمایلم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_9.mp3', '', 1761754199, 1761754199),
(31206, 'Hebrews 3:10', 'Hebrews', 3, 10, 'نو زه په قهر شوم هغه نسل ته او ومې ویل: زما نه لېرې دي تل د هغوی زړونه او نه غواړي چې وکړي عمل زما په حکمونو باندې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_10.mp3', '', 1761754199, 1761754199),
(31207, 'Hebrews 3:11', 'Hebrews', 3, 11, 'زه شوم په قهر او قسم مې وخوړ: ‹داخل به نه شي دوی هېڅکله هغه ځای ته چېرته چې زه به ورکومه ارامي ورته›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_11.mp3', '', 1761754199, 1761754199),
(31208, 'Hebrews 3:12', 'Hebrews', 3, 12, 'نو خویندو او ورونو، پام کوئ چې په تاسو کې دې د چا زړه داسې بد او بې‌ایمانه نه وي چې د ژوندي خدای څخه واوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_12.mp3', '', 1761754199, 1761754199),
(31209, 'Hebrews 3:13', 'Hebrews', 3, 13, 'بلکې هره ورځ یو بل هڅوئ، په داسې حال کې چې اوس هم موقعه شته چې په تاسو کې دې د ګناه د غولولو په وسیله د هېچا زړه سخت نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_13.mp3', '', 1761754199, 1761754199),
(31210, 'Hebrews 3:14', 'Hebrews', 3, 14, 'ځکه که چېرې مونږ تر اخره پورې په هغه باور واوسو چې د پیل نه مو درلود، نو مونږ به د عیسی سره ملګري شوي یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_14.mp3', '', 1761754199, 1761754199);